<?php

/* @autogenerated */
declare(strict_types=1);

namespace Tests\integration\Features\OAuth\Stub;

use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\ChallengesState;
use Civi\Lughauth\Features\OAuth\Client\Domain\ClientData;
use Civi\Lughauth\Features\OAuth\Session\Domain\Gateway\SessionStoreGateway;
use Civi\Lughauth\Features\OAuth\Session\Domain\SessionInfo;

class InMemorySessionStore implements SessionStoreGateway
{
    /** @var array<string, SessionInfo> */
    private array $sessions = [];

    public function loadSession(string $state): ?SessionInfo
    {
        return $this->sessions[$state] ?? null;
    }

    public function findActiveSession(string $sid, string $issuer): ?SessionInfo
    {
        $session = $this->sessions[$sid] ?? null;
        return $session !== null && $session->issuer === $issuer ? $session : null;
    }

    public function findActiveSessionIdByCsid(string $csid, string $issuer): ?string
    {
        foreach ($this->sessions as $state => $session) {
            if ($session->csid === $csid && $session->issuer === $issuer) {
                return $state;
            }
        }
        return null;
    }

    public function addSessionClient(string $state, string $issuer, string $clientId): void
    {
        $session = $this->findActiveSession($state, $issuer);
        if ($session !== null && !$session->hasClient($clientId)) {
            $this->sessions[$state] = new SessionInfo(
                csid: $session->csid,
                withMfa: $session->withMfa,
                issuer: $session->issuer,
                userId: $session->userId,
                clientId: $session->clientId,
                ssoClients: [...$session->ssoClients, $clientId],
            );
        }
    }

    public function saveSession(
        string $state,
        ClientData $clientDetails,
        string $issuer,
        ChallengesState $keypass,
        AuthenticationResult $validationData,
        string $csid,
        \DateInterval $expiration
    ): void {
        $this->sessions[$state] = new SessionInfo(
            csid: $csid,
            withMfa: $keypass->withMfa,
            issuer: $issuer,
            userId: (string) $validationData->id,
            clientId: $clientDetails->id,
        );
    }

    public function updateSession(string $newState, string $oldState): void
    {
        if (isset($this->sessions[$oldState])) {
            $this->sessions[$newState] = $this->sessions[$oldState];
            unset($this->sessions[$oldState]);
        }
    }

    public function deleteSession(string $state): void
    {
        unset($this->sessions[$state]);
    }

    public function purgeExpired(): void
    {
        // In-memory store has no expiry tracking; nothing to purge.
    }
}
